# =============================================================================
#  dev/cross-tool-sweep.R  --  ZY20: one row per external comparison tool
# =============================================================================
#  ZY20 asks for one row per tool: numbers, or an explicit `not_run` with the
#  reason measured on this host.  Nothing here invents a number.
#
#  Two kinds of row:
#    * measured  - recomputed from a CSV an earlier script wrote
#                  (`results/primer3-*.csv`, `results/specificity-oracle.csv`),
#                  or regenerated by that script under `--fresh`.
#    * not_run   - the tool cannot be run here; `cause` holds the observed fact
#                  (Sys.which() returned "", web-only form, licence gating),
#                  taken from the probe in this same run.
#
#  Primer3 is the regression anchor.  Its block must reproduce the numbers
#  VALIDATION.md already records (Tm r >= 0.999, mean offset +3.92 C, 17/20
#  loci with a pair in the 50-100 bp window, 5/8 agreement floor).  If a band
#  slips the script stops: that means this harness broke, not that the world
#  changed.  The same rule is written in ROADMAP.md's acceptance clause.
#
#  Run:  Rscript dev/cross-tool-sweep.R [--fresh] [--check]
#    --fresh  re-run dev/primer3-crosscheck.R, dev/specificity-oracle.R and
#             dev/as-tm-crosscheck.R instead of reusing their CSVs (~3 min, ~1 GB peak)
#    --check  exit non-zero if a row is malformed or a Primer3 band slipped
#  Writes .tmp/cross-tool-sweep.csv (git-ignored).
# =============================================================================

# ---- plumbing ----------------------------------------------------------------

sweep_root <- function() {
  script <- grep("^--file=", commandArgs(trailingOnly = FALSE), value = TRUE)
  if (length(script)) {
    return(dirname(dirname(normalizePath(sub("^--file=", "", script[[1L]])))))
  }
  wd <- getwd()
  repeat {
    if (file.exists(file.path(wd, "DESCRIPTION")) && dir.exists(file.path(wd, "R"))) {
      return(wd)
    }
    parent <- dirname(wd)
    if (identical(parent, wd)) {
      return(getwd())
    }
    wd <- parent
  }
}

root <- sweep_root()
opts <- commandArgs(trailingOnly = TRUE)
fresh <- "--fresh" %in% opts
check <- "--check" %in% opts
rscript <- file.path(R.home("bin"), "Rscript")

run_script <- function(name, label, wd = root) {
  cat(sprintf("--fresh: running %s (%s)\n", name, label))
  t0 <- proc.time()[["elapsed"]]
  old <- setwd(wd)
  on.exit(setwd(old), add = TRUE)
  status <- system2(rscript, file.path(root, "dev", name), stdout = TRUE, stderr = TRUE)
  elapsed <- proc.time()[["elapsed"]] - t0
  cat(tail(status, 3L), sep = "\n")
  attr(elapsed, "status") <- attr(status, "status")
  elapsed
}

results_dir <- file.path(root, "results")
csv_path <- function(name) file.path(results_dir, name)

# ---- the Primer3 anchor ------------------------------------------------------

need_fresh <- fresh || !file.exists(csv_path("primer3-thermo.csv")) ||
  !file.exists(csv_path("primer3-design.csv"))
p3_elapsed <- if (need_fresh) run_script("primer3-crosscheck.R", "thermo + 20 loci") else NA_real_

thermo <- utils::read.csv(csv_path("primer3-thermo.csv"), stringsAsFactors = FALSE)
design <- utils::read.csv(csv_path("primer3-design.csv"), stringsAsFactors = FALSE)

tm <- thermo[thermo$measure == "tm_c", ]
tm_ok <- is.finite(tm$pkg) & is.finite(tm$primer3)
tm_offset <- mean(tm$primer3[tm_ok] - tm$pkg[tm_ok])
tm_r <- stats::cor(tm$pkg[tm_ok], tm$primer3[tm_ok])
tm_rho <- stats::cor(tm$pkg[tm_ok], tm$primer3[tm_ok], method = "spearman")
tm_mg0 <- thermo[thermo$measure == "tm_c_pkg_at_mg0", ]
tm_mg0_offset <- mean(tm_mg0$primer3 - tm_mg0$pkg, na.rm = TRUE)
hp <- thermo[thermo$measure == "hairpin_dg", ]
hp_keep <- is.finite(hp$pkg) & is.finite(hp$primer3)
hp_delta <- hp$primer3[hp_keep] - hp$pkg[hp_keep]
dm <- thermo[thermo$measure == "heterodimer_dg", ]
dm_keep <- is.finite(dm$pkg) & is.finite(dm$primer3)
dm_delta <- dm$primer3[dm_keep] - dm$pkg[dm_keep]

n_loci <- nrow(design)
pairs_in_window <- sum(design$p3_n_pairs > 0L, na.rm = TRUE)
clears_all <- design$p3_any_pair_pass %in% TRUE
tract <- design[clears_all, ]
agreed <- sum(tract$has_assay, na.rm = TRUE)
tm_assays <- sum(design$has_assay, na.rm = TRUE)
both <- design[design$has_assay %in% TRUE & is.finite(design$p3_product), ]
amp_d <- both$tm_amplicon - both$p3_product
amp_rho <- if (nrow(both) >= 3L) {
  stats::cor(both$tm_amplicon, both$p3_product, method = "spearman")
} else {
  NA_real_
}
amp_within_25 <- sum(abs(amp_d) <= 25L)
wide_long <- sum(design$p3_product_wide > 100, na.rm = TRUE)
n_no_pair <- sum(design$p3_n_pairs == 0L, na.rm = TRUE)

# The bands VALIDATION.md records.  A slip here means the harness broke.
bands <- list(
  tm_r = tm_r >= 0.999,
  tm_offset = tm_offset >= 3.4 && tm_offset <= 4.4,
  pairs_in_window = pairs_in_window == 17L,
  agreed = agreed == 5L
)
if (!all(unlist(bands))) {
  stop(
    "Primer3 block no longer reproduces VALIDATION.md: ",
    paste(sprintf("%s=%s", names(bands), vapply(bands, function(x) {
      if (isTRUE(x)) "ok" else "SLIPPED"
    }, character(1))), collapse = ", "),
    sprintf(
      "\n  measured: tm r=%.4f offset=%+.2f C, %d/%d loci with a pair, %d/%d agreement",
      tm_r, tm_offset, pairs_in_window, n_loci, agreed, nrow(tract)
    ),
    "\n  That is a harness break, not a new result. Re-run `Rscript dev/primer3-crosscheck.R`.",
    call. = FALSE
  )
}

p3_runtime <- if (is.na(p3_elapsed)) NA_real_ else round(p3_elapsed / n_loci, 1)

p3_where <- sprintf(
  "amplicon median %+.0f bp (n = %d), rho %.3f; %d/%d loci no pair; %d/%d pairs rejected by a gate",
  stats::median(amp_d), nrow(both), amp_rho, n_no_pair, n_loci,
  sum(design$p3_any_pair_pass %in% FALSE), n_loci
)

# ---- the specificity baseline ------------------------------------------------

spec_path <- csv_path("specificity-oracle.csv")
spec_fresh <- fresh || !file.exists(spec_path)
spec_elapsed <- if (spec_fresh) run_script("specificity-oracle.R", "TAIR10 enumeration") else NA_real_
spec <- utils::read.csv(spec_path, stringsAsFactors = FALSE)

seed_rows <- spec[spec$test == "seed", ]
pcr_rows <- spec[spec$test == "pcr", ]
blast_rows <- spec[spec$test == "blast_full_length", ]
blast_where <- sprintf(
  "seed %d/%d equal, exact PCR %d/%d equal, %d exact full-length blastn hits; not a designer, a specificity baseline",
  sum(seed_rows$equal %in% TRUE), nrow(seed_rows),
  sum(pcr_rows$equal %in% TRUE), nrow(pcr_rows),
  nrow(blast_rows)
)

# ---- the tool registry -------------------------------------------------------
# status kinds: measured | absent | web | licence | paper
registry <- data.frame(
  tool = c(
    "Primer3 2.6.1", "UNAFold / mfold", "BLAST+ (blastn)",
    "Primer-BLAST", "BatchPrimer3", "MFEprimer-3.0", "isPcr (UCSC)",
    "EasyKASP", "NUPACK", "MELTING",
    "VCF2CAPS", "KASP-IEva", "LAMPrimers iQ", "ThermoPlex",
    "ARMSprimer3", "PrimerWeaver", "PyPCRtool", "PRISM",
    "Biopython Tm_NN"
  ),
  kind = c(
    "designer + thermo oracle", "thermo oracle (dG)", "specificity baseline",
    "designer", "designer", "designer + specificity", "specificity",
    "designer (KASP)", "thermo oracle", "thermo oracle",
    rep("designer", 8L),
    "allele-specific thermo oracle"
  ),
  probe = c(
    "primer3_core", "hybrid-ss-min", "blastn",
    NA, NA, "mfeprimer", "ispcr", "easykasp", "nupack", "melting",
    rep(NA_character_, 8L),
    "python3"
  ),
  status = c(
    "measured", "measured", "measured",
    "web", "web", "absent", "absent", "absent", "licence", "absent",
    rep("paper", 8L),
    "measured"
  ),
  stringsAsFactors = FALSE
)

not_run_cause <- function(kind, probe) {
  switch(kind,
    absent = sprintf('Sys.which("%s") == "" -- no binary in PATH', probe),
    web = "web service/form only -- needs network and manual submission; no local binary to run unattended",
    licence = "no binary; licence-gated (vendor terms do not allow an unattended run here)",
    paper = "publication code, web-only or not distributed as an installable tool on this host"
  )
}

# Probe every binary in this run, whether or not the row claims "absent".
probe_hits <- vapply(registry$probe, function(p) {
  if (is.na(p)) NA_character_ else Sys.which(p)
}, character(1))

# Biopython is a Python library, not a binary: probe the interpreter, then the
# import, then the CSV.  Any failure names the observed fact, as for not_run.
as_py <- ""
as_cause <- ""
if (!nzchar(probe_hits[registry$tool == "Biopython Tm_NN"])) {
  as_cause <- 'Sys.which("python3") == "" -- no interpreter for the Biopython leg'
} else {
  as_import <- suppressWarnings(system2(
    Sys.which("python3"), c("-c", shQuote("import Bio.SeqUtils.MeltingTemp")),
    stdout = FALSE, stderr = FALSE
  ))
  if (identical(as.integer(as_import), 0L)) {
    as_py <- Sys.which("python3")
  } else {
    as_cause <- 'python3 -c "import Bio.SeqUtils.MeltingTemp" exited non-zero -- Biopython not importable'
  }
}
as_csv <- csv_path("as-tm-crosscheck.csv")
as_elapsed <- NA_real_
if (nzchar(as_py) && (fresh || !file.exists(as_csv))) {
  as_elapsed <- run_script("as-tm-crosscheck.R", "8-row AS panel")
  st <- attr(as_elapsed, "status")
  if (!is.null(st) && st != 0L) {
    as_cause <- sprintf(
      "dev/as-tm-crosscheck.R exited %d (OligoArrayAux or Biopython missing -- see its output)", st
    )
  }
}
as_df <- if (nzchar(as_py) && file.exists(as_csv)) {
  tryCatch(utils::read.csv(as_csv, stringsAsFactors = FALSE), error = function(e) NULL)
} else {
  NULL
}

rows <- lapply(seq_len(nrow(registry)), function(i) {
  r <- registry[i, ]
  if (r$status == "measured") {
    if (r$tool == "Primer3 2.6.1") {
      return(c(
        tool = r$tool, kind = r$kind, status = "measured",
        oracle = "oligotm / ntthal 2.6.1, same conditions",
        loci = sprintf("%d", n_loci),
        pairs_50_100 = sprintf("%d/%d", pairs_in_window, n_loci),
        runtime_s = if (is.na(p3_runtime)) "reused" else sprintf("%.1f", p3_runtime),
        where_diverged = p3_where, cause = ""
      ))
    }
    if (r$tool == "UNAFold / mfold") {
      return(c(
        tool = r$tool, kind = r$kind, status = "measured (not independent)",
        oracle = "ntthal -a HAIRPIN / ANY",
        loci = "", pairs_50_100 = "",
        runtime_s = "reused",
        where_diverged = sprintf(
          "hairpin dG mean %+.2f kcal/mol (n = %d); heterodimer %+.2f (n = %d); NOT independent -- hybrid-ss-min is the engine oligo_dg() calls",
          mean(hp_delta), length(hp_delta), mean(dm_delta), length(dm_delta)
        ),
        cause = ""
      ))
    }
    if (r$tool == "Biopython Tm_NN") {
      if (nzchar(as_cause) || is.null(as_df) || nrow(as_df) != 8L) {
        return(c(
          tool = r$tool, kind = r$kind, status = "not_run",
          oracle = "", loci = "", pairs_50_100 = "", runtime_s = "",
          where_diverged = "",
          cause = if (nzchar(as_cause)) {
            as_cause
          } else {
            "results/as-tm-crosscheck.csv missing or not 8 rows -- run dev/as-tm-crosscheck.R"
          }
        ))
      }
      return(c(
        tool = r$tool, kind = r$kind, status = "measured",
        oracle = "Biopython Tm_NN (DNA_NN3 + DNA_TMM1), same salt and strand conditions",
        loci = sprintf("%d", nrow(as_df)), pairs_50_100 = "",
        runtime_s = if (is.na(as_elapsed)) "reused" else sprintf("%.1f", as_elapsed),
        where_diverged = sprintf(
          "dtm > 0 %d/%d, dgap > 0 %d/%d; median dtm penultimate %+.2f C vs terminal %+.2f C; Spearman rho(dtm, discrimination) %+.3f (reported, not asserted)",
          sum(as_df$dtm > 0), nrow(as_df), sum(as_df$dgap > 0), nrow(as_df),
          stats::median(as_df$dtm[as_df$geom == 1L]),
          stats::median(as_df$dtm[as_df$geom == 0L]),
          stats::cor(as_df$dtm, as_df$discrimination, method = "spearman")
        ),
        cause = ""
      ))
    }
    return(c(
      tool = r$tool, kind = r$kind, status = "measured",
      oracle = "enumeration on TAIR10 (dev/specificity-oracle.R)",
      loci = "", pairs_50_100 = "",
      runtime_s = sprintf("%.2f", mean(blast_rows$seconds, na.rm = TRUE)),
      where_diverged = blast_where, cause = ""
    ))
  }
  c(
    tool = r$tool, kind = r$kind, status = "not_run",
    oracle = "", loci = "", pairs_50_100 = "", runtime_s = "",
    where_diverged = "", cause = not_run_cause(r$status, r$probe)
  )
})
out <- do.call(rbind, lapply(rows, function(x) as.data.frame(as.list(x), stringsAsFactors = FALSE)))

# A claimed-absent binary that is suddenly present is a finding, not a row to
# quietly flip: the return gate in ROADMAP.md says "install it, then repeat".
newly_present <- registry$tool[!is.na(registry$probe) &
  registry$status == "absent" & nzchar(probe_hits)]
if (length(newly_present)) {
  cat(sprintf(
    "\nNEWLY PRESENT on this host: %s\n  The ZY20 return gate is open for these; run their blocks.\n",
    paste(newly_present, collapse = ", ")
  ))
}

# ---- print and write ---------------------------------------------------------

cat("\n===== CROSS-TOOL SWEEP (ZY20) =====\n")
cat(sprintf("host probes: %s\n\n", paste(
  sprintf(
    "%s=%s", registry$probe[!is.na(registry$probe) & registry$status == "measured"],
    ifelse(nzchar(probe_hits[!is.na(registry$probe) & registry$status == "measured"]), "yes", "no")
  ),
  collapse = ", "
)))
print(out[, c("tool", "kind", "status", "loci", "pairs_50_100", "runtime_s")], row.names = FALSE)
cat("\n-- where each measured tool diverged --\n")
for (i in which(out$status != "not_run")) {
  cat(sprintf("  %-18s %s\n", out$tool[i], out$where_diverged[i]))
}
cat("\n-- not_run, with the cause measured in this run --\n")
for (i in which(out$status == "not_run")) {
  cat(sprintf("  %-18s %s\n", out$tool[i], out$cause[i]))
}

tmp_dir <- file.path(root, ".tmp")
dir.create(tmp_dir, showWarnings = FALSE, recursive = TRUE)
utils::write.csv(out, file.path(tmp_dir, "cross-tool-sweep.csv"), row.names = FALSE)

cat(sprintf(
  "\nPrimer3 anchor: Tm r = %.3f, mean %+.2f C (Mg=0: %+.2f C), %d/%d loci with a pair, %d/%d agreement\n",
  tm_r, tm_offset, tm_mg0_offset, pairs_in_window, n_loci, agreed, nrow(tract)
))
cat(sprintf(
  "measured %d / not_run %d of %d tools; wrote .tmp/cross-tool-sweep.csv\n",
  sum(out$status != "not_run"), sum(out$status == "not_run"), nrow(out)
))

if (check) {
  bad <- out$status == "not_run" & !nzchar(out$cause)
  if (any(bad)) {
    cat(sprintf("CHECK FAILED: %d not_run rows have no named cause\n", sum(bad)))
    quit(status = 1L)
  }
  cat("check: every row is measured or not_run-with-a-cause, Primer3 bands hold\n")
}
